/**
 * The on-screen keyboard, for the full-screen frames that take a typed
 * answer (a session's spelling card, dictation, a sentence of one's own).
 *
 * Those frames are pinned to the window (`position: fixed; inset: 0`) so the
 * answer buttons never move. With the keyboard up that stops working, in
 * two different ways:
 * - Android's web view shrinks the window to what is above the keyboard,
 *   and a frame laid out for the whole phone then scrolls its own card out
 *   of sight: the prompt goes under the heading on a small phone.
 * - The iPhone's web view keeps the window as it was and lays the keyboard
 *   over it, so the input and the Check button sit behind the keys.
 * Both report the part that is still visible as `window.visualViewport`.
 * The frame follows that box while somebody is typing in it, and on a short
 * one drops what can wait (the chips row, the big heading) so the prompt,
 * the input and its button stay on screen together.
 *
 * Pure decision here with tests (`softKeyboard.test.ts`); the hook only
 * measures; the frame wears `keyboardAttributes(view)`: `data-keyboard="open"`,
 * `data-compact` and the `--kb-top` / `--kb-view` sizes its CSS reads.
 */
import { useEffect, useState, type RefObject } from 'react';

/**
 * How much of the window must be gone before it counts as a keyboard. Less
 * than the smallest phone keyboard (about 200 px with no suggestion row),
 * more than a browser's address bar folding away (about 60–90 px), which
 * also changes the visible height and is not a keyboard.
 */
export const KEYBOARD_MIN_PX = 120;

/**
 * Below this visible height the frame drops its chrome while typing. A
 * tablet or a tall phone keeps everything; a phone held upright with the
 * keyboard up (roughly 380–600 px left) is compacted.
 */
export const COMPACT_BELOW_PX = 640;

export interface KeyboardView {
  open: boolean;
  /** Compact the frame: keep prompt, input and its button only. */
  compact: boolean;
  /** The visible box, in CSS pixels, when open. */
  top: number;
  height: number;
}

export const CLOSED: KeyboardView = { open: false, compact: false, top: 0, height: 0 };

export interface KeyboardFacts {
  /** `visualViewport.height` (or `innerHeight` where there is none). */
  visibleHeight: number;
  /** `visualViewport.offsetTop`: how far the iPhone scrolled the page up. */
  offsetTop: number;
  /** The tallest visible height seen at this width: the window without a keyboard. */
  fullHeight: number;
  /** Whether a text field inside the frame has the focus. */
  editing: boolean;
}

/** Whether a keyboard is up over this frame, and how to lay it out. */
export function keyboardView(facts: KeyboardFacts): KeyboardView {
  if (!facts.editing) return CLOSED;
  if (facts.fullHeight - facts.visibleHeight < KEYBOARD_MIN_PX) return CLOSED;
  const height = Math.max(0, Math.round(facts.visibleHeight));
  return {
    open: true,
    compact: height < COMPACT_BELOW_PX,
    top: Math.max(0, Math.round(facts.offsetTop)),
    height,
  };
}

/** Whether this element takes typing. */
export function isTextField(element: Element | null): boolean {
  if (element === null) return false;
  if (element instanceof HTMLTextAreaElement) return !element.disabled && !element.readOnly;
  if (element instanceof HTMLInputElement) {
    const nonText = ['button', 'checkbox', 'radio', 'range', 'submit', 'reset', 'file', 'color', 'image'];
    return !nonText.includes(element.type) && !element.disabled && !element.readOnly;
  }
  return element instanceof HTMLElement && element.isContentEditable;
}

/** What the frame wears for a view: the attributes and sizes its CSS reads. */
export function keyboardAttributes(view: KeyboardView): {
  'data-keyboard'?: 'open';
  'data-compact'?: '';
  style?: React.CSSProperties;
} {
  if (!view.open) return {};
  return {
    'data-keyboard': 'open',
    ...(view.compact ? { 'data-compact': '' as const } : {}),
    style: {
      '--kb-top': `${String(view.top)}px`,
      '--kb-view': `${String(view.height)}px`,
    } as React.CSSProperties,
  };
}

/**
 * Follows the keyboard for the frame in `frame` and keeps the field being
 * typed in on screen. The frame spreads `keyboardAttributes(view)`.
 */
export function useSoftKeyboard(frame: RefObject<HTMLElement | null>): KeyboardView {
  const [view, setView] = useState<KeyboardView>(CLOSED);

  useEffect(() => {
    const viewport = window.visualViewport;
    let width = window.innerWidth;
    let fullHeight = Math.max(window.innerHeight, viewport?.height ?? 0);
    let last = CLOSED;

    const measure = (): void => {
      const element = frame.current;
      if (element === null) return;
      // A turn of the phone or a resized window starts the measure again.
      if (window.innerWidth !== width) {
        width = window.innerWidth;
        fullHeight = 0;
      }
      const visibleHeight = viewport?.height ?? window.innerHeight;
      const active = document.activeElement;
      const editing = isTextField(active) && element.contains(active);
      // The window with no keyboard is the tallest one seen while nobody
      // types; a keyboard only ever takes height away.
      if (!editing && !last.open) fullHeight = Math.max(fullHeight, window.innerHeight, visibleHeight);
      else fullHeight = Math.max(fullHeight, visibleHeight);
      const next = keyboardView({
        visibleHeight,
        offsetTop: viewport?.offsetTop ?? 0,
        fullHeight,
        // Once open, the frame stays laid out for the keyboard until the
        // keyboard itself has gone: a tap on Check moves the focus first,
        // and a frame that grew back under the finger would move the button.
        editing: editing || last.open,
      });
      if (next.open && (!last.open || next.height !== last.height) && active instanceof HTMLElement) {
        // After the frame has its new size: the prompt above the field
        // first (the web view scrolled the field's box to show it, which can
        // hide the prompt), then the field itself if it no longer fits.
        requestAnimationFrame(() => {
          for (let box = active.parentElement; box !== null && box !== element; box = box.parentElement) {
            if (box.scrollTop > 0) box.scrollTop = 0;
          }
          if ('scrollIntoView' in active) active.scrollIntoView({ block: 'nearest' });
        });
      }
      if (next.open !== last.open || next.compact !== last.compact || next.height !== last.height) {
        last = next;
        setView(next);
      }
    };

    measure();
    viewport?.addEventListener('resize', measure);
    viewport?.addEventListener('scroll', measure);
    window.addEventListener('resize', measure);
    // Focus moves before the keyboard has finished arriving; the resize
    // that follows measures again.
    document.addEventListener('focusin', measure);
    document.addEventListener('focusout', measure);
    return () => {
      viewport?.removeEventListener('resize', measure);
      viewport?.removeEventListener('scroll', measure);
      window.removeEventListener('resize', measure);
      document.removeEventListener('focusin', measure);
      document.removeEventListener('focusout', measure);
    };
  }, [frame]);

  return view;
}
